import sys

lines = sys.stdin.read().splitlines()
n = int(lines[0])
counts = {"ERROR": 0, "WARN": 0, "INFO": 0}
for i in range(1, n + 1):
    level = lines[i].split(maxsplit=1)[0]
    if level in counts:
        counts[level] += 1
print(f"ERROR={counts['ERROR']} WARN={counts['WARN']} INFO={counts['INFO']}")
